const base = {"model": "claude-opus-5-5", "max_tokens": 16000, "system": "You are a claims intake specialist. Extract every field of the claims schema from the packet: policy_number, claimant_name, phone, loss_date, loss_location, police_report_number, vin, vehicle_year, vehicle_make, vehicle_model, injuries, estimated_amount_usd, damage_severity. damage_severity is minor, moderate or severe, judged from the photo. injuries is yes or no. Give a confidence per field. Lower the confidence when documents disagree, when a value fails a format check (a VIN is 17 characters with a valid check digit), or when it is a guess. Prefer the police report over the phone note when they conflict, and say so in notes.", "output_config": {"format": {"type": "json_schema", "schema": {"$defs": {"ExtractedField": {"properties": {"name": {"description": "one of the claims-schema field names", "title": "Name", "type": "string"}, "value": {"anyOf": [{"type": "string"}, {"type": "null"}], "description": "normalised value; dates as YYYY-MM-DD; null if not found", "title": "Value"}, "confidence": {"description": "0-1: how sure you are this value is right", "title": "Confidence", "type": "number"}, "source": {"description": "police_report | phone_note | damage_photo | both", "title": "Source", "type": "string"}}, "required": ["name", "value", "confidence", "source"], "title": "ExtractedField", "type": "object", "additionalProperties": false}}, "properties": {"claim_id": {"title": "Claim Id", "type": "string"}, "fields": {"items": {"$ref": "#/$defs/ExtractedField"}, "title": "Fields", "type": "array"}, "notes": {"description": "conflicts between documents, unreadable parts", "title": "Notes", "type": "string"}}, "required": ["claim_id", "fields", "notes"], "title": "ClaimExtraction", "type": "object", "additionalProperties": false}}}};
const p = $json.body;
const content = [
  {type: 'document', source: {type: 'base64', media_type: 'application/pdf', data: p.police_report_pdf_b64}},
  {type: 'image', source: {type: 'base64', media_type: 'image/png', data: p.damage_photo_b64}},
  {type: 'text', text: 'Phone note:\n' + p.phone_note + '\nClaim id: ' + p.claim_id},
];
return [{json: {claim_id: p.claim_id, claude_request: {...base, messages: [{role: 'user', content}]}}}];

const ex = JSON.parse($json.content.find(b => b.type === 'text').text);
const minConf = Math.min(...ex.fields.map(f => f.confidence));
const rec = Object.fromEntries(ex.fields.map(f => [f.name, f.value]));
return [{json: {...ex, record: rec, min_confidence: minConf,
  low_fields: ex.fields.filter(f => f.confidence < 0.8).map(f => f.name)}}];
